local terminal    = "kitty"
local fileManager = "dolphin"
local menu        = "fuzzel"

local liveWallpaper =
    "/home/3ty6six7/Pictures/Wallpapers/live/miyabi-looking-up-at-the-gray-sky-zenless-zone-zero-moewalls-com.mp4"

local toggleWaybarCmd = [[
    bash -lc '
        if pgrep -x waybar >/dev/null; then
            pkill -x waybar
        else
            waybar >/tmp/waybar.log 2>&1 &
        fi
    '
]]

local liveWallpaperCmd =
    'mpvpaper ALL "' .. liveWallpaper ..
    '" -o "no-audio loop-file=inf hwdec=auto"'

-- Startup system dashboard
local systemDashboard = [[
    kitty --class sysinfo --title Sysinfo \
        zsh -lc 'clear; fastfetch; echo; ~/.config/hypr/scripts/sysinfo-panel.sh; exec zsh'
]]

-------------------
---- AUTOSTART ----
-------------------

hl.on("hyprland.start", function()
    -- Core session
    hl.exec_cmd("playerctld daemon")
    hl.exec_cmd("hyprctl setcursor Bibata-Modern-Ice 20")
    hl.exec_cmd("nm-applet")
    -- hl.exec_cmd("fcitx5")

    -- Desktop
    -- hl.exec_cmd(liveWallpaperCmd)
    hl.exec_cmd("hyprpaper")
    hl.exec_cmd("waybar")
    hl.exec_cmd("dunst")

    -- System
    hl.exec_cmd("/usr/lib/polkit-kde-authentication-agent-1")
    hl.exec_cmd("hypridle")

    -- Startup dashboard
    hl.exec_cmd(systemDashboard)
    hl.exec_cmd("sleep 1 && hyprlock")
end)

